// Simple SQL migration & seeder runner for MSSQL.
//
// Two independent histories, each with its own folder and tracking table:
//   migrations/*.sql -> SchemaMigrations  (schema: CREATE/ALTER TABLE, index, ...)
//   seeders/*.sql    -> SchemaSeeders     (data: master data, menu FITUR/OTORISASI, sample rows)
//
// Only files directly under the folder are used (not migrations/tables/, which
// holds full CREATE TABLE dumps generated by generate:tables, not incremental
// migrations). Pending files run in filename order; batches are split on
// standalone GO lines. Run migrations before seeders, since seeders depend on
// the tables.
//
// Usage:
//   node scripts/migrate.js                   apply pending migrations
//   node scripts/migrate.js --seed            apply pending seeders
//   node scripts/migrate.js [--seed] --baseline
//                                              mark all current files as applied
//                                              without running them (for adopting
//                                              this runner in an environment where
//                                              the .sql files were already applied
//                                              by hand)
const fs = require('fs');
const path = require('path');
const db = require('../database');

const TARGETS = {
    migration: { dir: path.join(__dirname, '..', 'migrations'), table: 'SchemaMigrations', label: 'migrasi' },
    seeder: { dir: path.join(__dirname, '..', 'seeders'), table: 'SchemaSeeders', label: 'seeder' },
};

async function ensureTrackingTable(pool, table) {
    await pool.request().query(`
        IF NOT EXISTS (SELECT 1 FROM sys.tables WHERE name = '${table}')
        BEGIN
            CREATE TABLE ${table} (
                filename NVARCHAR(255) NOT NULL PRIMARY KEY,
                appliedAt DATETIME NOT NULL DEFAULT GETDATE()
            );
        END
    `);
}

function listSqlFiles(dir) {
    if (!fs.existsSync(dir)) return [];
    return fs
        .readdirSync(dir, { withFileTypes: true })
        .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
        .map((entry) => entry.name)
        .sort();
}

async function getAppliedFilenames(pool, table) {
    const result = await pool.request().query(`SELECT filename FROM ${table}`);
    return new Set(result.recordset.map((row) => row.filename));
}

async function runSqlFile(pool, dir, filename) {
    const sqlScript = fs.readFileSync(path.join(dir, filename), 'utf8');
    const batches = sqlScript
        .split(/^\s*GO\s*$/im)
        .map((batch) => batch.trim())
        .filter((batch) => batch.length > 0);

    for (const batch of batches) {
        await pool.request().query(batch);
    }
}

async function main() {
    const baseline = process.argv.includes('--baseline');
    const target = TARGETS[process.argv.includes('--seed') ? 'seeder' : 'migration'];
    const pool = await db.poolPromise;

    await ensureTrackingTable(pool, target.table);
    const applied = await getAppliedFilenames(pool, target.table);
    const pending = listSqlFiles(target.dir).filter((filename) => !applied.has(filename));

    if (pending.length === 0) {
        console.log(`Tidak ada ${target.label} baru.`);
        process.exit(0);
    }

    for (const filename of pending) {
        if (baseline) {
            console.log(`Baseline (skip eksekusi): ${filename}`);
        } else {
            console.log(`Menjalankan ${target.label}: ${filename}`);
            await runSqlFile(pool, target.dir, filename);
        }
        await pool
            .request()
            .input('filename', db.sql.NVarChar, filename)
            .query(`INSERT INTO ${target.table} (filename) VALUES (@filename)`);
    }

    console.log(`Selesai. ${pending.length} ${target.label} ${baseline ? 'ditandai sebagai sudah diterapkan' : 'dijalankan'}.`);
    process.exit(0);
}

// Jalankan ulang semua seeder (tanpa cek SchemaSeeders); dipakai fitur reset data di development.
// Aman karena seeder wajib idempotent.
async function rerunAllSeeders(pool) {
    const target = TARGETS.seeder;
    const files = listSqlFiles(target.dir);
    for (const filename of files) {
        await runSqlFile(pool, target.dir, filename);
    }
    return files;
}

if (require.main === module) {
    main().catch((err) => {
        console.error('Gagal:', err.message);
        console.error(err);
        process.exit(1);
    });
}

module.exports = { rerunAllSeeders };
